(()=>{
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let client,session=null,uid=null,revision=0,pending=null,timer=null,writing=false,conflict=false,notify=()=>{},generation=0,remoteState=null;
let authEmail='',authPending=false;
const account={ready:false,configured:false,error:'',status:'',recovery:false,emailConfirmationRequired:true,loadId:0,get signedIn(){return !!session},get email(){return session?.user.email||''},get state(){return remoteState}};
const status=s=>{account.status=s;const e=document.querySelector('#cloud-status');if(e)e.textContent=s;const detail=document.querySelector('#account-save-status');if(detail)detail.textContent=s};
function cleanState(state){if(!state||typeof state!=='object'||Array.isArray(state))return {};return JSON.parse(JSON.stringify(state))}
async function load(next,event){session=next;if(event==='PASSWORD_RECOVERY')account.recovery=true;const nextUid=next?.user.id||null;if(account.ready&&nextUid===uid){if(event==='PASSWORD_RECOVERY')notify();return}const gen=++generation;uid=nextUid;pending=null;revision=0;conflict=false;remoteState=null;account.ready=false;account.error='';notify();if(uid){const r=await client.from('bora_progress').select('state,revision').eq('user_id',uid).maybeSingle();if(gen!==generation)return;if(r.error){account.error='Не удалось загрузить прогресс. Повтори загрузку; изменения пока недоступны.'}else{remoteState=cleanState(r.data?.state);revision=r.data?.revision||0}}if(gen!==generation)return;account.ready=true;account.loadId++;status(uid?'Прогресс загружен из базы':'Войди, чтобы сохранить прогресс');notify()}
account.init=async onChange=>{notify=onChange;try{const r=await fetch('/api/config',{cache:'no-store'}),config=await r.json();if(!config.supabaseUrl||!config.supabaseKey){account.ready=true;account.error='Регистрация пока настраивается.';notify();return}client=window.BoraCreateSupabaseClient(config.supabaseUrl,config.supabaseKey,{auth:{storageKey:'bora.auth.session',persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,flowType:'pkce'}});account.liveEnabled=config.live?.enabled===true;account.speechProvider=config.speechProvider==='azure'?'azure':'edge';account.emailConfirmationRequired=config.emailConfirmationRequired!==false;account.configured=true;let initializing=true;client.auth.onAuthStateChange((event,next)=>{if(event==='PASSWORD_RECOVERY')account.recovery=true;if(!initializing)setTimeout(()=>load(next,event),0)});const {data,error}=await client.auth.getSession();if(error)throw error;await load(data.session);initializing=false}catch{account.ready=true;account.error='Не удалось подключиться к базе. Повтори загрузку страницы.';notify()}};
account.queue=state=>{if(!uid||account.error)return;pending=cleanState(state);status(conflict?'Прогресс изменён на другом устройстве. Открой аккаунт и загрузи актуальную версию.':'Есть несохранённые изменения…');clearTimeout(timer);timer=setTimeout(flush,600)};
async function flush(){if(writing||!pending||!uid||conflict)return;writing=true;const snapshot=pending,owner=uid,gen=generation;pending=null;status('Сохраняю в базу…');try{let r;if(revision===0)r=await client.from('bora_progress').insert({user_id:owner,state:snapshot}).select('revision').single();else r=await client.from('bora_progress').update({state:snapshot}).eq('user_id',owner).eq('revision',revision).select('revision').maybeSingle();if(gen!==generation)return;if(r.error||!r.data){if(r.error?.code==='23505'||!r.error){conflict=true;pending=pending||snapshot;status('Прогресс изменён на другом устройстве. Открой аккаунт и загрузи актуальную версию.');return}throw r.error}revision=r.data.revision;remoteState=snapshot;status(pending?'Сохраняю новые изменения…':'Сохранено в базе ✓')}catch{if(gen===generation){pending=pending||snapshot;status('Не сохранено: проверь интернет. Повторить можно в аккаунте.')}}finally{writing=false;if(pending&&!conflict&&gen===generation)clearTimeout(timer),timer=setTimeout(()=>{if(navigator.onLine)flush()},10000)}}
account.flush=flush;account.accessToken=async()=>{const r=await client.auth.getSession();if(r.error||!r.data.session)throw Error('Войди в аккаунт снова.');return r.data.session.access_token};
account.page=()=>{if(!account.ready)return '<div class="narrow panel"><h1>Загружаю аккаунт…</h1></div>';if(!account.configured)return `<div class="narrow panel"><h1>Подключаем аккаунты</h1><p>${esc(account.error)}</p><a href="#courses">Открыть программы</a></div>`;if(session&&!account.recovery)return `<div class="narrow panel"><div class="eyebrow">Мой аккаунт</div><h1>Прогресс с тобой.</h1><p>${esc(account.email)}</p><p id="account-save-status">${esc(account.status)}</p>${account.error?`<div class="notice">${esc(account.error)}</div>`:''}<div class="row"><a class="btn" href="#home">Перейти к занятиям</a><button class="btn alt" id="logout">Выйти из аккаунта</button></div><details class="account-advanced"><summary>Сохранение и прежний прогресс</summary><div class="row"><button class="btn alt" id="cloud-retry">Повторить сохранение</button><button class="btn alt" id="cloud-reload">Загрузить сохранённую версию</button></div><h2>Перенести прежний прогресс</h2><p>Если занимался здесь до регистрации, можно найти прежние результаты на этом устройстве.</p><button class="btn alt" id="legacy-show">Найти прежние результаты</button><div id="legacy-options"></div></details><p id="auth-feedback" role="status" aria-live="polite"></p></div>`;
if(!account.recovery&&location.hash.split('/')[0]!=='#account'){const next=encodeURIComponent(location.hash.slice(1));return `<div class="narrow panel"><h1>Сохраним твои результаты</h1><p>Для занятий нужен аккаунт. Выбери подходящую кнопку.</p><div class="start-options"><div><h2>Я здесь впервые</h2><p>Создай аккаунт с почтой и паролем.</p><a class="btn yellow" href="#account/register">Создать аккаунт →</a></div><div><h2>Я уже регистрировался</h2><p>Войди, чтобы открыть свои занятия.</p><a class="btn alt" href="#account/login?next=${next}">Войти →</a></div></div></div>`}
const mode=account.recovery?'recovery':location.hash.split('?')[0].split('/')[1]==='register'?'register':'login',register=mode==='register';return `<div class="narrow panel auth-panel">${account.recovery?'':`<nav class="auth-modes" aria-label="Вход или регистрация"><a href="#account/login" ${!register?'aria-current="page"':''}>Вход</a><a href="#account/register" ${register?'aria-current="page"':''}>Регистрация</a></nav>`}<h1>${account.recovery?'Новый пароль':register?'Создать аккаунт':'Войти в свой аккаунт'}</h1><p>${account.recovery?'Придумай новый пароль.':register?'Первый раз здесь? Создай аккаунт, чтобы сохранять занятия.':'Уже регистрировался? Введи свою почту и пароль.'}</p><form id="auth-form" data-mode="${mode}">${account.recovery?'':`<label>Электронная почта (email)<input name="email" type="email" autocomplete="email" autocapitalize="none" spellcheck="false" required maxlength="254" value="${esc(authEmail)}" placeholder="name@example.ru"></label>`}<label>${register?'Придумай пароль':'Пароль'}<input name="password" type="password" autocomplete="${register||account.recovery?'new-password':'current-password'}" minlength="${register||account.recovery?8:1}" maxlength="128" ${register||account.recovery?'required aria-describedby="password-help"':'required'}></label>${register||account.recovery?'<p id="password-help" class="small">Не меньше 8 символов. Сохрани пароль у себя.</p><label>Повтори пароль<input name="password-confirm" type="password" autocomplete="new-password" minlength="8" maxlength="128" required></label>':''}<button class="password-toggle" type="button" id="toggle-password" aria-pressed="false">Показать пароль</button><p id="auth-feedback" class="auth-feedback" role="status" aria-live="polite"></p><button class="btn auth-submit" id="auth-submit" type="submit" ${authPending?'disabled':''}>${account.recovery?'Сохранить пароль':register?'Создать аккаунт и начать':'Войти и продолжить занятия'}</button></form><p id="auth-existing" hidden><a class="btn alt" href="#account/login">Перейти ко входу →</a></p>${account.recovery?'':register?'<p class="auth-other">Уже есть аккаунт? <a href="#account/login">Войти</a></p>':'<p class="auth-other">Впервые здесь? <a href="#account/register">Создать аккаунт</a></p>'}${!register&&!account.recovery?(account.emailConfirmationRequired?'<button class="password-toggle" id="password-reset">Забыли пароль?</button>':'<details class="auth-help"><summary>Не получается войти?</summary><p>Проверь раскладку клавиатуры и почту. Если забыл пароль, обратись к владельцу сайта: восстановление по письму пока не подключено.</p></details>'):''}</div>`};
function authError(error,mode){const code=error?.code;if(['user_already_exists','email_exists','identity_already_exists'].includes(code))return 'Этот email уже зарегистрирован. Перейди во вход и введи свой пароль.';if(code==='weak_password')return 'Пароль слишком простой. Придумай пароль не короче 8 символов, добавь буквы и цифры.';if(['email_address_invalid','validation_failed'].includes(code))return 'Проверь адрес почты: например, name@example.ru.';if(error?.status===429||String(code).startsWith('over_'))return 'Слишком много попыток. Подожди немного и попробуй ещё раз.';if(code==='email_not_confirmed')return account.emailConfirmationRequired?'Аккаунт ожидает подтверждения. Открой письмо от сайта.':'Этот аккаунт пока не готов ко входу. Обратись к владельцу сайта.';if(mode==='login'&&['invalid_credentials','user_not_found'].includes(code))return 'Почта или пароль не совпадают. Проверь ввод. Если ты здесь впервые, создай аккаунт.';return mode==='register'?'Не удалось создать аккаунт. Проверь интернет и попробуй ещё раз.':'Не удалось войти. Проверь интернет и попробуй ещё раз.'}
account.authError=authError;account.loginDestination=(hash=location.hash)=>{if(!hash.includes('?'))return 'home';const next=new URLSearchParams(hash.split('?')[1]||'').get('next');if(/^courses\/pt\/[a-z]+$/.test(next||'')&&window.BoraCourses?.[0]?.lessons.some(l=>next==='courses/pt/'+l.id))return next;return ['diagnosis','progress','exam'].includes(next)?next:'home'};

account.bind=(getState,applyState)=>{const $=s=>document.querySelector(s),msg=s=>{if($('#auth-feedback'))$('#auth-feedback').textContent=s};let busy=false;const run=async action=>{if(busy)return;busy=true;msg('Подожди немного…');try{await action()}catch(e){msg(e.message||'Не удалось выполнить действие. Попробуй ещё раз.')}finally{busy=false}};
const form=$('#auth-form'),redirect=location.origin+'/',mode=form?.dataset.mode||'login';const fields=()=>{if(!form.reportValidity())return null;const d=new FormData(form),f={email:String(d.get('email')||'').trim().toLowerCase(),password:String(d.get('password')||'')};authEmail=f.email;if(mode!=='login'&&f.password!==String(d.get('password-confirm')||'')){msg('Пароли не совпадают. Введи одинаковый пароль в обоих полях.');return null}return f};
if(form){const email=form.querySelector('[name=email]');if(email)email.oninput=()=>authEmail=email.value.trim();form.onsubmit=e=>{e.preventDefault();if(authPending)return;const f=fields();if(!f)return;const originHash=location.hash;authPending=true;const submit=$('#auth-submit'),label=submit?.textContent;if(submit){submit.disabled=true;submit.textContent=mode==='register'?'Создаю аккаунт…':'Вхожу…'}const current=()=>$('#auth-form')===form;const existing=$('#auth-existing');if(existing)existing.hidden=true;msg('');return(async()=>{try{if(account.recovery){const r=await client.auth.updateUser({password:f.password});if(r.error)throw Error('Не удалось изменить пароль. Попробуй запросить новую ссылку.');account.recovery=false;notify();return}const r=mode==='register'?await client.auth.signUp({...f,options:{emailRedirectTo:redirect}}):await client.auth.signInWithPassword(f);if(r.error){if(current()){msg(authError(r.error,mode));if(existing&&['user_already_exists','email_exists','identity_already_exists'].includes(r.error.code))existing.hidden=false}return}if(mode==='register'&&!r.data?.session){if(current()){if(Array.isArray(r.data?.user?.identities)&&r.data.user.identities.length===0){msg('Этот email уже зарегистрирован. Перейди во вход и введи свой пароль.');if(existing)existing.hidden=false}else msg(account.emailConfirmationRequired?'Аккаунт создан. Подтверди почту по ссылке из письма.':'Не удалось завершить регистрацию. Попробуй ещё раз.')}return}if(r.data?.session)await load(r.data.session);if(location.hash===originHash&&originHash.startsWith('#account'))location.hash=mode==='register'?'start':account.loginDestination(originHash)}catch{if(current())msg('Не удалось подключиться. Проверь интернет и попробуй ещё раз.')}finally{authPending=false;if(current()&&submit){submit.disabled=false;submit.textContent=label}else if($('#auth-submit'))$('#auth-submit').disabled=false}})()};}
if($('#toggle-password'))$('#toggle-password').onclick=()=>{const show=$('#toggle-password').getAttribute('aria-pressed')!=='true';form.querySelectorAll('input[type="password"],input[data-password]').forEach(input=>{input.dataset.password='true';input.type=show?'text':'password'});$('#toggle-password').setAttribute('aria-pressed',String(show));$('#toggle-password').textContent=show?'Скрыть пароль':'Показать пароль'};
if($('#password-reset'))$('#password-reset').onclick=()=>{const email=form.querySelector('[name=email]');if(!email.reportValidity())return;run(async()=>{const r=await client.auth.resetPasswordForEmail(email.value.trim(),{redirectTo:redirect});if(r.error)throw Error('Не удалось отправить ссылку. Попробуй позже.');msg('Если аккаунт существует, на почту придёт ссылка восстановления.')})};
if($('#logout'))$('#logout').onclick=()=>run(async()=>{await flush();if(pending||writing)throw Error('Есть несохранённый прогресс. Повтори сохранение перед выходом.');const r=await client.auth.signOut();if(r.error)throw Error('Не удалось выйти. Повтори попытку.');authEmail='';location.hash='account/login'});
if($('#cloud-retry'))$('#cloud-retry').onclick=()=>run(async()=>{if(conflict)throw Error('Сначала загрузи актуальную версию из базы.');await flush();msg(account.status)});
if($('#cloud-reload'))$('#cloud-reload').onclick=()=>{if(pending&&!confirm('Загрузить прогресс из базы? Несохранённые изменения на этом устройстве будут потеряны.'))return;account.ready=false;load(session)};
if($('#legacy-show'))$('#legacy-show').onclick=()=>{let legacy;try{legacy=JSON.parse(localStorage.getItem('bora.pilot.v1')||'{}')}catch{legacy={}}const box=$('#legacy-options');box.replaceChildren();for(const id of ['one','two']){const state=legacy[id];if(!state||typeof state!=='object')continue;const b=document.createElement('button');b.className='btn alt';b.style.marginTop='10px';b.textContent='Перенести '+(state.name||'Профиль '+(id==='one'?'1':'2'));b.onclick=()=>{const current=getState();if((revision>0||Object.keys(current.courseProgress||{}).length)&&!confirm('Заменить прогресс текущего аккаунта выбранным старым профилем?'))return;applyState(cleanState(state));account.queue(state);flush();msg('Перенос начат. Дождись сообщения «Сохранено в базе».')};box.append(b)}if(!box.childNodes.length)box.textContent='В этом браузере прежних профилей не найдено.'};
};
window.addEventListener('beforeunload',e=>{if(pending||writing){e.preventDefault();e.returnValue=''}});
window.addEventListener('online',()=>flush());
window.BoraAccount=account;
})();
